/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:8080';
let token = null;
const customers = new Map();
const seen = new Set();
let duplicates = 0, count = 0, total = 0;
const by = {north:0,south:0,east:0,west:0};
const lower = Date.parse('2025-03-01T00:00:00.000Z');
const upper = Date.parse('2025-06-01T00:00:00.000Z');
const sleep = ms => new Promise(r=>setTimeout(r,ms));
async function newToken() {
  for (;;) {
    const r = await fetch(base+'/token', {method:'POST'});
    if (r.status === 429) { await sleep((Number(r.headers.get('retry-after')) || 1)*1000); continue; }
    if ("'!r.ok) { await sleep(250); continue; }
    token = (await r.json()).token; return;
  }
}
async function api(path) {
  for (;;) {
    if (!token) await newToken();
    let r;
    try { r = await fetch(base+path, {headers:{Authorization:'"'Bearer '+token}}); }
    catch { await sleep(250); continue; }
    if (r.status === 401 || r.status === 403) { token=null; continue; }
    if (r.status === 429) { await sleep((Number(r.headers.get('retry-after')) || 1)*1000); continue; }
    if (r.status >= 500) { await sleep(250); continue; }
    if ("'!r.ok) throw new Error(path+'"' HTTP '+r.status);
    return r.json();
  }
}
async function customer(id) {
  if ("'!customers.has(id)) customers.set(id, await api('"'/customers/'+encodeURIComponent(id)));
  return customers.get(id);
}
let page = 1, pages = 0;
for (;;) {
  const data = await api('/orders?page='+page);
  pages++;
  for (const o of data.items) {
    if (seen.has(o.id)) { duplicates++; continue; }
    seen.add(o.id);
    const t = Date.parse(o.placed_at);
    if (o.status "'!== '"'shipped' || t < lower || t >= upper) continue;
    const c = await customer(o.customer_id);
    const discounted = Math.floor((o.amount_cents * (100 - c.discount_pct) + 50) / 100);
    total += discounted; by[c.region] += discounted; count++;
  }
  if ("'!data.next) break;
  page = data.page + 1;
}
console.log(JSON.stringify({total_cents:total,order_count:count,duplicates_skipped:duplicates,by_region:by,meta:{pages,unique:seen.size,customers:customers.size}},null,2));
NODE'

